" cy="130" rx="40" ry="95"/><ellipse cx="150" cy="130" rx="95" ry="35"/><path d="M55 130h190M150 35v190"/></svg></div></article><article class="tt-slide" role="group" aria-roledescription="slide" aria-label="4 of 4" hidden inert><div><p class="tt-kicker">TECHTRAC LTD / DIGITAL SERVICES</p><h2>Moving your website? <span>Start with a plan.</span></h2><p class="tt-sub">Tell us about your website, domain and email setup to discuss migration requirements.</p><a class="tt-button" href="{{ url('/client/contact') }}">CONTACT TECHTRAC</a></div><div class="tt-art"><svg viewBox="0 0 300 260" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><circle cx="150" cy="130" r="95"/><ellipse cx="150" cy="130" rx="40" ry="95"/><ellipse cx="150" cy="130" rx="95" ry="35"/><path d="M55 130h190M150 35v190"/></svg></div></article><div class="tt-home-controls" hidden><button type="button" class="tt-arrow" data-prev aria-label="Previous slide">←</button><button type="button" class="tt-arrow" data-next aria-label="Next slide">→</button></div><p class="tt-sr" aria-live="polite" data-status></p></div></section><script>(()=>{const r=document.querySelector('[data-tt-carousel]');if(!r||r.dataset.ready)return;r.dataset.ready='true';let i=0;const slides=[...r.querySelectorAll('.tt-slide')];function show(n){i=(n+slides.length)%slides.length;slides.forEach((s,k)=>{s.hidden=k!==i;s.inert=k!==i});r.querySelector('[data-status]').textContent='Slide '+(i+1)+' of '+slides.length}r.querySelector('.tt-home-controls').hidden=false;r.querySelector('[data-prev]').onclick=()=>show(i-1);r.querySelector('[data-next]').onclick=()=>show(i+1);r.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();show(i+(e.key==='ArrowRight'?1:-1))}})})();</script>